import Foundation

// Versions generated by the repository: X.Y.Z[-rc.N[.devN]]. Numeric fields
// compare as decimal strings, so long build IDs cannot overflow an integer.
public struct ReleaseVersion: Comparable {
    private let fields: [String]
    public init(_ value: String) throws {
        let pattern = "^([0-9]+)\\.([0-9]+)\\.([0-9]+)(?:-rc\\.([0-9]+)(?:\\.dev([0-9]+))?)?$"
        let regex = try NSRegularExpression(pattern: pattern)
        let ns = value as NSString
        guard let match = regex.firstMatch(in: value, range: NSRange(location: 0, length: ns.length)) else { throw AgentError.unsupportedRelease }
        func component(_ i: Int) -> String {
            guard match.range(at: i).location != NSNotFound else { return "" }
            let raw = ns.substring(with: match.range(at: i)).drop(while: { $0 == "0" })
            return raw.isEmpty ? "0" : String(raw)
        }
        let rc = component(4), dev = component(5)
        fields = [component(1), component(2), component(3), rc.isEmpty ? "1" : "0", rc, dev.isEmpty ? "1" : "0", dev]
    }
    public static func < (left: Self, right: Self) -> Bool {
        for (a, b) in zip(left.fields, right.fields) where a != b {
            return a.count == b.count ? a < b : a.count < b.count
        }
        return false
    }
}
